using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
internal static class TrimEastFloor {
 struct V {public Vector3 p,n;public Vector2 uv;public float x;public static V Mix(V a,V b,float t)=>new V{p=Vector3.Lerp(a.p,b.p,t),n=Vector3.Lerp(a.n,b.n,t).normalized,uv=Vector2.Lerp(a.uv,b.uv,t),x=Mathf.Lerp(a.x,b.x,t)};}
 [MenuItem("Tools/Dungeon Tavern/Trim East Floor Half")]
 static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Scenes/SealRoom/SealRoom_B1.unity");var tiles=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("EastExtension_")).ToArray();if(tiles.Length!=14||tiles.Any(t=>!t.GetComponentInChildren<MeshFilter>()&&!t.GetComponentInChildren<SpriteRenderer>()))throw new Exception("Expected 14 mesh tiles");var backup="ArtSource/Backups/TrimEastFloor_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(scene);File.Copy(scene.path,backup+"/SealRoom_B1.unity");const string folder="Assets/DungeonTavern/Art/Environment/Architecture/FloorClipping/EastHalf";if(AssetDatabase.IsValidFolder(folder))throw new Exception("Already trimmed");AssetDatabase.CreateFolder(Path.GetDirectoryName(folder),"EastHalf");int index=0;
 foreach(var tile in tiles){var mf=tile.GetComponentInChildren<MeshFilter>();if(!mf){var sr=tile.GetComponentInChildren<SpriteRenderer>();var sprite=sr.sprite;var sourceMesh=new Mesh();sourceMesh.vertices=sprite.vertices.Select(v=>new Vector3(v.x,v.y,0)).ToArray();sourceMesh.uv=sprite.uv;sourceMesh.triangles=sprite.triangles.Select(i=>(int)i).ToArray();sourceMesh.RecalculateNormals();sourceMesh.RecalculateBounds();var g=new GameObject("CroppedFloorVisual");g.transform.SetParent(sr.transform,false);mf=g.AddComponent<MeshFilter>();mf.sharedMesh=sourceMesh;var mr=g.AddComponent<MeshRenderer>();var materialPath=folder+"/Floor_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(sprite.texture))+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.SetTexture("_BaseMap",sprite.texture);mat.SetColor("_BaseColor",sr.color);mat.SetFloat("_Cull",0);AssetDatabase.CreateAsset(mat,materialPath);}mr.sharedMaterial=mat;mr.sortingLayerID=sr.sortingLayerID;mr.sortingOrder=sr.sortingOrder;Undo.RecordObject(sr,"Keep original sprite disabled");sr.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(sr);}var source=mf.sharedMesh;var bounds=mf.GetComponent<Renderer>().bounds;float cut=bounds.center.x;var vertices=source.vertices;var normals=source.normals;var uv=source.uv;var output=new List<V>();var mesh=new Mesh{name="EastFloorHalf_"+index};mesh.subMeshCount=source.subMeshCount;var sub=new List<int[]>();for(int s=0;s<source.subMeshCount;s++){var result=new List<int>();var tri=source.GetTriangles(s);for(int i=0;i<tri.Length;i+=3){var poly=new List<V>();foreach(int j in tri.Skip(i).Take(3))poly.Add(new V{p=vertices[j],n=normals[j],uv=uv[j],x=mf.transform.TransformPoint(vertices[j]).x});var clipped=new List<V>();for(int j=0;j<poly.Count;j++){var a=poly[j];var b=poly[(j+1)%poly.Count];bool ina=a.x<=cut,inb=b.x<=cut;if(ina)clipped.Add(a);if(ina!=inb)clipped.Add(V.Mix(a,b,(cut-a.x)/(b.x-a.x)));}if(clipped.Count<3)continue;int start=output.Count;output.AddRange(clipped);for(int j=1;j<clipped.Count-1;j++)result.AddRange(new[]{start,start+j,start+j+1});}sub.Add(result.ToArray());}mesh.vertices=output.Select(v=>v.p).ToArray();mesh.normals=output.Select(v=>v.n).ToArray();mesh.uv=output.Select(v=>v.uv).ToArray();for(int s=0;s<sub.Count;s++)mesh.SetTriangles(sub[s],s);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,folder+"/"+mesh.name+".asset");Undo.RecordObject(mf,"Crop outer half of floor");mf.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(mf);foreach(var c in tile.GetComponentsInChildren<Collider>()){Undo.RecordObject(c,"Crop floor collision");if(c is MeshCollider mc)mc.sharedMesh=mesh;else if(c is BoxCollider bc){var cb=bc.bounds;if(cb.max.x<=cut)continue;float width=Mathf.Max(0,cut-cb.min.x);var newCenter=cb.center;newCenter.x=cb.min.x+width/2;var axis=bc.transform.InverseTransformVector(Vector3.right);var size=bc.size;int k=Mathf.Abs(axis.x)>Mathf.Abs(axis.y)?0:1;if(Mathf.Abs(axis.z)>Mathf.Abs(axis[k]))k=2;size[k]*=width/cb.size.x;bc.center=bc.transform.InverseTransformPoint(newCenter);bc.size=size;}PrefabUtility.RecordPrefabInstancePropertyModifications(c);}var after=mf.GetComponent<Renderer>().bounds;if(Mathf.Abs(after.min.x-bounds.min.x)>.001f||Mathf.Abs(after.size.x-.5f)>.001f)throw new Exception("Incorrect trim");index++;}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("ArtSource/Previews/B1GateLanding/trim.txt","14 tiles cropped to inner half (0.5 width); inner edge fixed; UV interpolated, no texture squeeze; backup="+backup);}
}
